        return "清除 active-run 指针必须由当前操作者 prompt 明确授权；切换 run 请使用受控 --set-active/setup/resume。"

    if MEMORY_PATH_RE.search(text) and not contract.get("memory_approved"):
        memory_read = tool in {"Read", "Grep", "Glob"} or (
